-- Frozen pre-optimization source projection for equivalence and bounded profiling.
SELECT crm_property_contact_claims.id, crm_property_contact_claims.owner_key, crm_property_contact_claims.property_key, crm_property_contact_claims.import_id, crm_property_contact_claims.list_id, crm_property_contact_claims.source_sheet, crm_property_contact_claims.source_row_number, crm_property_contact_claims.contact_name, crm_property_contact_claims.phone_primary, crm_property_contact_claims.phone_alternate, crm_property_contact_claims.email_primary, crm_property_contact_claims.area_name, crm_property_contact_claims.project_name, crm_property_contact_claims.building_name, crm_property_contact_claims.unit_number, crm_property_contact_claims.property_type, crm_property_contact_claims.party_role, crm_property_contact_claims.procedure_type, crm_property_contact_claims.transaction_date, crm_property_contact_claims.transaction_price_aed, crm_property_contact_claims.ownership_status, crm_property_contact_claims.confidence_score, crm_property_contact_claims.match_reason, crm_property_contact_claims.latest_sale_date, crm_property_contact_claims.latest_sale_price_aed, crm_property_contact_claims.later_sale_date, crm_property_contact_claims.lead_id, crm_property_contact_claims.unit_candidate_key, crm_property_contact_claims.lease_end, crm_property_contact_claims.annual_rent_aed, crm_property_contact_claims.created_at, crm_property_contact_claims.updated_at, history_evidence.resolver_version AS claim_resolver_version, history_evidence.event_family, CAST(history_evidence.cadastral_identity ->> 'property_key' AS VARCHAR) AS cadastral_key, history_evidence.scoped_identity_collision AS identity_collision, CAST(json_strip_nulls(json_build_object('source_size_unit', history_evidence.source_size_unit, 'source_fields', json_build_object('size_sqft', history_evidence.source_fields -> 'size_sqft', 'size_sqm', history_evidence.source_fields -> 'size_sqm', 'size_unknown', history_evidence.source_fields -> 'size_unknown', 'property_type', history_evidence.source_fields -> 'property_type', 'unit_number', history_evidence.source_fields -> 'unit_number', 'area_name', history_evidence.source_fields -> 'area_name', 'master_project', history_evidence.source_fields -> 'master_project', 'project_name', history_evidence.source_fields -> 'project_name', 'building_name', history_evidence.source_fields -> 'building_name', 'building_number', history_evidence.source_fields -> 'building_number', 'property_number', history_evidence.source_fields -> 'property_number', 'plot_number', history_evidence.source_fields -> 'plot_number', 'plot_pre_reg_number', history_evidence.source_fields -> 'plot_pre_reg_number', 'transaction_price_aed', history_evidence.source_fields -> 'transaction_price_aed'), 'original_identifiers', history_evidence.original_identifiers, 'original_property_fields', history_evidence.original_property_fields, 'inferred_size_unit', history_evidence.inferred_size_unit, 'amount_first_match', history_evidence.amount_first_match, 'property_identity_match', history_evidence.property_identity_match, 'owner_match_policy', history_evidence.owner_match_policy, 'source_file_sha256', history_evidence.source_file_sha256, 'source_identifiers', history_evidence.source_identifiers, 'source_area_field', history_evidence.source_area_field, 'source_filename', history_evidence.source_filename, 'address_recovery', history_evidence.address_recovery, 'inferred_file_context', history_evidence.inferred_file_context, 'source_registry_location_resolution', history_evidence.source_registry_location_resolution, 'property_identity_resolution', history_evidence.property_identity_resolution, 'cadastral_identity', history_evidence.cadastral_identity, 'file_context', history_evidence.file_context, 'registry_unit_fallback', history_evidence.registry_unit_fallback, 'unit_hierarchy_resolution', history_evidence.unit_hierarchy_resolution, 'source_unit_number', history_evidence.source_unit_number, 'duplicate_count', history_evidence.duplicate_count, 'source_audit', history_evidence.source_audit, 'owner_match', history_evidence.owner_match, 'broker_contact', history_evidence.broker_contact)) AS VARCHAR) AS history_evidence_json, crm_contact_lists.name AS source_list_name
FROM crm_property_contact_claims JOIN LATERAL json_to_record(crm_property_contact_claims.evidence) AS history_evidence(resolver_version VARCHAR, event_family VARCHAR, cadastral_identity JSON, scoped_identity_collision BOOLEAN, source_fields JSON, source_size_unit VARCHAR, property_identity_resolution JSON, file_context JSON, registry_unit_fallback JSON, unit_hierarchy_resolution JSON, source_unit_number VARCHAR, duplicate_count JSON, source_audit JSON, original_identifiers JSON, original_property_fields JSON, inferred_size_unit JSON, amount_first_match JSON, property_identity_match JSON, owner_match_policy VARCHAR, source_file_sha256 VARCHAR, source_identifiers JSON, source_area_field VARCHAR, source_filename VARCHAR, address_recovery JSON, inferred_file_context JSON, source_registry_location_resolution JSON, owner_match JSON, broker_contact JSON) ON true JOIN crm_contact_lists ON crm_contact_lists.id = crm_property_contact_claims.list_id AND crm_contact_lists.organization_id = :org
WHERE crm_property_contact_claims.import_id = :import_id AND crm_property_contact_claims.organization_id = :org
